                continue
            s=sum(sim(T[len(T)-ov+i],B[i]) for i in range(ov))/ov
            avg=s
        # prefer higher avg, tie smaller d
        key=(round(avg,3), -d)
        if best is None or key>best[0]:
            best=(key,d,avg)
    d=best[1]
