cd /app && cat > recon4.py << 'PY'
import glob, re
from difflib import SequenceMatcher
files = sorted(glob.glob('hf/*.png.txt'))
def norm(s): return re.sub(r'\s+',' ', s.strip().lower())
def body(txt):
    lines=[l.rstrip() for l in txt.splitlines()]
    out=[l for l in lines if not (('Score:' in l) and ('Moves:' in l))]
    while out and out[0].strip()=='': out.pop(0)
    while out and out[-1].strip()=='': out.pop()
    if out: out=out[:-1]
    while out and out[-1].strip()=='': out.pop()
    return out
raw=[body(open(f,encoding='utf-8',errors='replace').read()) for f in files]
# dedup consecutive identical
frames=[]
for B in raw:
    if not B: continue
    if frames and [norm(x) for x in frames[-1]]==[norm(x) for x in B]:
        continue
    frames.append(B)
def sim(a,b):
    a=norm(a); b=norm(b)
    if a==b: return 1.0
    if not a or not b: return 0.0
    return SequenceMatcher(None,a,b).ratio()
T=[]
MAXS=10
dhist={}
for B in frames:
    if not T: T=list(B); continue
    cand=[]
    for s in range(0,MAXS+1):
        ov=len(B)-s
        if ov<=0 or ov>len(T): continue
        avg=sum(sim(T[len(T)-ov+i],B[i]) for i in range(ov))/ov
        cand.append((s,ov,avg))
    # pick smallest s with avg>=0.8; else max avg
    good=[c for c in cand if c[2]>=0.8]
    if good:
        s=min(good,key=lambda c:c[0])[0]
    elif cand:
        s=max(cand,key=lambda c:c[2])[0]
    else:
        s=len(B)
    dhist[s]=dhist.get(s,0)+1
    for nl in B[len(B)-s:]: T.append(nl)
open('transcript4.txt','w').write('\n'.join(T))
print("frames",len(frames),"lines",len(T),"dhist",dict(sorted(dhist.items())))
PY
